import { prisma } from '@/lib/prisma';
import { Card, Tag, Rate } from 'antd';
import Link from 'next/link';

export default async function Home() {
  // Lấy 12 sản phẩm đang hiển thị (isActive: true) từ Database
  const products = await prisma.product.findMany({
    where: { isActive: true },
    take: 12,
    orderBy: { id: 'asc' },
  });

  // Hàm format giá tiền VNĐ
  const formatPrice = (price: number) => 
    new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(price);

  return (
    <div className="min-h-screen bg-gray-50 pb-10">
      {/* Header */}
      <header className="bg-white shadow-sm sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <h1 className="text-2xl font-bold text-blue-600">ENICE</h1>
          <Link href="/admin" className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition">
            Quản trị Admin
          </Link>
        </div>
      </header>

      {/* Danh sách sản phẩm */}
      <main className="max-w-7xl mx-auto px-4 py-8">
        <h2 className="text-2xl font-bold mb-6 text-gray-800">Sản phẩm nổi bật</h2>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {products.map((product) => (
            <Card
              key={product.id}
              hoverable
              cover={
                <div className="h-56 overflow-hidden bg-gray-100 relative">
                  {/* Lưu ý: Ảnh phải được copy vào thư mục public/key/ */}
                  <img 
  src={`/${product.img1.replace(/\\/g, '/')}`} 
  alt={product.name}
  className="w-full h-full object-cover"
/>
                  {product.isTopseller && (
                    <Tag color="gold" className="absolute top-2 left-2 font-semibold">
                      🔥 Top Bán Chạy
                    </Tag>
                  )}
                  {product.salePrice && (
                    <Tag color="red" className="absolute top-2 right-2 font-semibold">
                      -{Math.round((1 - product.salePrice / product.price) * 100)}%
                    </Tag>
                  )}
                </div>
              }
            >
              <div className="flex flex-col gap-2">
                <Tag color="blue" className="w-fit">{product.brand}</Tag>
                <h3 className="font-semibold text-lg line-clamp-2 min-h-[3.5rem]">{product.name}</h3>
                <Rate disabled defaultValue={product.rating} className="text-sm" />
                
                <div className="mt-2">
                  {product.salePrice ? (
                    <div className="flex items-center gap-2">
                      <span className="text-red-600 font-bold text-lg">{formatPrice(product.salePrice)}</span>
                      <span className="text-gray-400 line-through text-sm">{formatPrice(product.price)}</span>
                    </div>
                  ) : (
                    <span className="text-red-600 font-bold text-lg">{formatPrice(product.price)}</span>
                  )}
                </div>
              </div>
            </Card>
          ))}
        </div>
      </main>
    </div>
  );
}